input.command:
# Check soak test status
if [ -f /tmp/ivx-soak-results.json ]; then
  cat /tmp/ivx-soak-results.json | bun -e '
    try {
      const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
      const elapsed = d.startTime ? ((d.lastUpdate || Date.now()) - d.startTime) / 60000 : 0;
      console.log("=== SOAK STATUS ===");
      console.log(`Started: ${new Date(d.startTime).toISOString()}`);
      console.log(`Last update: ${d.lastUpdate ? new Date(d.lastUpdate).toISOString() : "N/A"}`);
      console.log(`Elapsed: ${elapsed.toFixed(1)} min / 120 min target`);
      console.log(`Total requests: ${d.totalRequests}`);
      console.log(`Pass: ${d.passCount}  Fail: ${d.failCount}`);
      console.log(`Cold-start 502s: ${d.coldStart502s ?? "N/A"}`);
      console.log(`4xx errors: ${d.clientErrors ?? 0}`);
      console.log(`Timeouts: ${d.timeouts ?? 0}`);
      console.log(`Restarts: ${d.restarts ?? 0}`);
      console.log(`Queue stalls: ${d.queueStalls ?? 0}`);
      console.log(`DB failures: ${d.dbFailures ?? 0}`);
      console.log(`Provider failures: ${d.providerFailures ?? 0}`);
      console.log(`SHA mismatches: ${d.shaMismatches ?? 0}`);
      console.log(`P50: ${d.p50LatencyMs ?? "N/A"}ms  P95: ${d.p95LatencyMs ?? "N/A"}ms`);
      console.log(`Max latency: ${d.maxLatencyMs ?? "N/A"}ms`);
    } catch(e) { console.log("Error:", e.message); }
  '
else
  echo "No soak results file found"
fi

echo ""
echo "=== Soak monitor process ==="
ps aux | grep -i soak | grep -v grep || echo "Soak monitor NOT running"

