const TARGET_MS = 2 * 60 * 60 * 1000; // 2 hours
const INTERVAL_MS = 30_000;
const RESULTS_FILE = "/tmp/ivx-soak-results.json";
const LOG_FILE = "/tmp/ivx-soak-log.txt";

interface SoakResults {
  startTime: number;
  lastUpdate: number;
  totalRequests: number;
  passCount: number;
  failCount: number;
  coldStart502s: number;
  clientErrors: number;
  timeouts: number;
  restarts: number;
  queueStalls: number;
  dbFailures: number;
  providerFailures: number;
  shaMismatches: number;
  p50LatencyMs: number;
  p95LatencyMs: number;
  p99LatencyMs: number;
  maxLatencyMs: number;
  latencies: number[];
  status: "running" | "complete";
  productionSha: string | null;
}

function loadResults(): SoakResults {
  if (existsSync(RESULTS_FILE)) {
    try {
      const r = JSON.parse(readFileSync(RESULTS_FILE, "utf8"));
      // If previous run reached 2 hours, start fresh
      if (r.status === "complete" || (r.lastUpdate - r.startTime) >= TARGET_MS) {
        return freshResults();
      }
      // If previous run is incomplete, continue it
      r.status = "running";
      return r;
    } catch { return freshResults(); }
  }
  return freshResults();
}

function freshResults(): SoakResults {
  return {
    startTime: Date.now(),
    lastUpdate: Date.now(),
    totalRequests: 0,
    passCount: 0,
    failCount: 0,
    coldStart502s: 0,
    clientErrors: 0,
    timeouts: 0,
    restarts: 0,
    queueStalls: 0,
    dbFailures: 0,
    providerFailures: 0,
    shaMismatches: 0,
    p50LatencyMs: 0,
    p95LatencyMs: 0,
    p99LatencyMs: 0,
    maxLatencyMs: 0,
    latencies: [],
    status: "running",
    productionSha: null,
  };
}

function saveResults(r: SoakResults) {
  r.lastUpdate = Date.now();
  r.p50LatencyMs = r.latencies.length > 0 ? r.latencies.sort((a,b) => a-b)[Math.floor(r.latencies.length * 0.5)] : 0;
  r.p95LatencyMs = r.latencies.length > 0 ? r.latencies.sort((a,b) => a-b)[Math.floor(r.latencies.length * 0.95)] : 0;
  r.p99LatencyMs = r.latencies.length > 0 ? r.latencies.sort((a,b) => a-b)[Math.floor(r.latencies.length * 0.99)] : 0;
  r.maxLatencyMs = r.latencies.length > 0 ? Math.max(...r.latencies) : 0;
  writeFileSync(RESULTS_FILE, JSON.stringify(r, null, 2));
}

function log(msg: string) {
  const ts = new Date().toISOString();
  const line = `[${ts}] ${msg}`;
  writeFileSync(LOG_FILE, line + "\n", { flag: "a" });
  console.log(line);
}

async function checkEndpoint(url: string): Promise<{ ok: boolean; status: number; latency: number; sha: string | null; dbOk: boolean; is502: boolean; isTimeout: boolean }> {
  const start = Date.now();
  try {
    const res = await fetch(`${url}/health`, { signal: AbortSignal.timeout(25000) });
    const latency = Date.now() - start;
    if (res.status === 502) return { ok: false, status: 502, latency, sha: null, dbOk: false, is502: true, isTimeout: false };
    const text = await res.text();
    if (text.includes("<!DOCTYPE html>")) return { ok: false, status: 502, latency, sha: null, dbOk: false, is502: true, isTimeout: false };
    try {
      const data = JSON.parse(text);
      const sha = data.sha ?? data.gitSha ?? data.commit ?? null;
      const dbOk = data.db === true || data.databaseConfigured === true;
      const aiOk = data.aiOk === true;
      const queueDepth = data.queueDepth ?? 0;
      return { ok: data.status === "healthy", status: res.status, latency, sha, dbOk, is502: false, isTimeout: false };
    } catch {
      return { ok: false, status: res.status, latency, sha: null, dbOk: false, is502: false, isTimeout: false };
    }
  } catch (e) {
    const latency = Date.now() - start;
    const isTimeout = e instanceof Error && (e.name === "TimeoutError" || e.message.includes("abort"));
    return { ok: false, status: 0, latency, sha: null, dbOk: false, is502: false, isTimeout };
  }
}

async function checkChat(url: string): Promise<{ ok: boolean; status: number; latency: number; is502: boolean }> {
  const start = Date.now();
  try {
    const res = await fetch(`${url}/api/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message: "ping", conversationId: "soak-test" }),
      signal: AbortSignal.timeout(30000),
    });
    const latency = Date.now() - start;
    if (res.status === 502) return { ok: false, status: 502, latency, is502: true };
    if (res.status >= 400 && res.status < 500) return { ok: false, status: res.status, latency, is502: false };
    return { ok: res.status >= 200 && res.status < 300, status: res.status, latency, is502: false };
  } catch (e) {
    const latency = Date.now() - start;
    return { ok: false, status: 0, latency, is502: false };
  }
}

async function main() {
  let results = loadResults();
  const elapsed = (results.lastUpdate - results.startTime) / 60000;
  log(`Soak monitor starting. Elapsed so far: ${elapsed.toFixed(1)} min. Target: 120 min.`);

  let firstSha: string | null = results.productionSha;

  while ((Date.now() - results.startTime) < TARGET_MS) {
    const target = URLS[results.totalRequests % URLS.length];
    const healthResult = await checkEndpoint(target.url);
    results.totalRequests++;
    results.latencies.push(healthResult.latency);

    if (healthResult.ok) {
      results.passCount++;
      if (healthResult.sha) {
        if (!firstSha) {
          firstSha = healthResult.sha;
          results.productionSha = firstSha;
          log(`First SHA captured: ${firstSha}`);
        } else if (healthResult.sha !== firstSha) {
          results.shaMismatches++;
          log(`SHA MISMATCH: expected ${firstSha}, got ${healthResult.sha}`);
        }
      }
      if (!healthResult.dbOk) results.dbFailures++;
      log(`[${target.name}] PASS status=${healthResult.status} latency=${healthResult.latency}ms sha=${healthResult.sha?.slice(0,8) ?? "N/A"}`);
    } else {
      results.failCount++;
      if (healthResult.is502) {
        results.coldStart502s++;
        log(`[${target.name}] COLD_START_502 latency=${healthResult.latency}ms`);
      } else if (healthResult.isTimeout) {
        results.timeouts++;
        log(`[${target.name}] TIMEOUT latency=${healthResult.latency}ms`);
      } else if (healthResult.status >= 400 && healthResult.status < 500) {
        results.clientErrors++;
        log(`[${target.name}] CLIENT_ERROR status=${healthResult.status} latency=${healthResult.latency}ms`);
      } else {
        results.restarts++;
        log(`[${target.name}] FAIL status=${healthResult.status} latency=${healthResult.latency}ms`);
      }
    }

    // Every 10th request, also test chat endpoint
    if (results.totalRequests % 10 === 0 && healthResult.ok) {
      const chatResult = await checkChat(target.url);
      if (!chatResult.ok) {
        log(`[${target.name}] CHAT_FAIL status=${chatResult.status} latency=${chatResult.latency}ms`);
      }
    }

    saveResults(results);
    await Bun.sleep(INTERVAL_MS);
  }

  results.status = "complete";
  saveResults(results);
  const totalElapsed = (results.lastUpdate - results.startTime) / 60000;
  log(`SOAK COMPLETE. Elapsed: ${totalElapsed.toFixed(1)} min. Total: ${results.totalRequests}. Pass: ${results.passCount}. Fail: ${results.failCount}. 502s: ${results.coldStart502s}. SHA mismatches: ${results.shaMismatches}. P50: ${results.p50LatencyMs}ms. P95: ${results.p95LatencyMs}ms.`);
}

main().catch(e => log(`FATAL: ${e}`));
