   213|/** Server-side password grant against the Supabase Auth token endpoint (legacy fallback only). */
   214|async function passwordGrant(supabaseUrl: string, email: string, password: string): Promise<{
   215|  ok: boolean;
   216|  accessToken?: string;
   217|  refreshToken?: string;
   218|  expiresAt?: number;
   219|  errorMessage?: string;
   220|  errorStatus?: number;
   221|}> {
   222|  const endpoint = `${supabaseUrl.replace(/\/+$/, '')}/auth/v1/token?grant_type=password`;
   223|  const anonKey = resolveAnonKey();
   224|  if (!anonKey) {
   225|    return { ok: false, errorMessage: 'Supabase anon key is not configured on the backend.' };
   226|  }
   227|  const controller = new AbortController();
   228|  const timer = setTimeout(() => controller.abort(), 20_000);
   229|  try {
   230|    const response = await fetch(endpoint, {
   231|      method: 'POST',
   232|      headers: {
   233|        'Content-Type': 'application/json',
   234|        apikey: anonKey,
   235|        Authorization: `Bearer ${anonKey}`,
   236|      },
   237|      body: JSON.stringify({ email, password }),
   238|      signal: controller.signal,
   239|    });
   240|    const text = await response.text();
   241|    let parsed: Record<string, unknown> = {};
   242|    try {
   243|      parsed = text ? (JSON.parse(text) as Record<string, unknown>) : {};
   244|    } catch {
   245|      return { ok: false, errorMessage: `Supabase returned non-JSON auth response (HTTP ${response.status}).` };
   246|    }
   247|    if (!response.ok) {
   248|      const message = typeof parsed.error_description === 'string'
   249|        ? parsed.error_description
   250|        : typeof parsed.msg === 'string'
   251|          ? parsed.msg
   252|          : typeof parsed.error === 'string'
   253|            ? parsed.error
   254|            : `Supabase rejected the password grant (HTTP ${response.status}).`;
   255|      return { ok: false, errorMessage: message, errorStatus: response.status };
   256|    }
   257|    const accessToken = typeof parsed.access_token === 'string' ? parsed.access_token : '';
   258|    const refreshToken = typeof parsed.refresh_token === 'string' ? parsed.refresh_token : '';
   259|    const expiresAt = typeof parsed.expires_at === 'number' ? parsed.expires_at : 0;
   260|    if (!accessToken || !refreshToken) {
   261|      return { ok: false, errorMessage: 'Supabase did not return access_token/refresh_token.' };
   262|    }
   263|    return { ok: true, accessToken, refreshToken, expiresAt };
   264|  } catch (error) {
   265|    return { ok: false, errorMessage: error instanceof Error ? error.message : 'Network failure during password grant.' };
   266|  } finally {
   267|    clearTimeout(timer);
   268|  }
