   288|  // EMERGENCY-ONLY GATE: passwordless login is restricted to emergency recovery.
   289|  // The owner must use standard email + password sign-in for routine access.
   290|  // This endpoint is kept as a last-resort lockout recovery path only.
   291|  const emergency = readTrimmed(body.emergency).toLowerCase();
   292|  if (emergency !== 'true' && emergency !== 'ivx_emergency_recovery') {
   293|    const failure: OwnerSessionFailure = {
   294|      success: false,
   295|      message: 'Passwordless owner login is emergency-only. Please sign in with your email and password. If you are locked out, include { "emergency": "ivx_emergency_recovery" } in the request body.',
   296|      rootCause: 'passwordless_not_emergency_mode',
   297|      deploymentMarker: DEPLOYMENT_MARKER,
   298|      timestamp: nowIso(),
   299|    };
   300|    return ownerOnlyJson(failure, 403);
   301|  }
   302|
   303|  if (!isValidEmail(email)) {
   304|    const failure: OwnerSessionFailure = {
   305|      success: false,
   306|      message: 'A valid owner email is required.',
   307|      rootCause: 'missing_or_invalid_email',
   308|      deploymentMarker: DEPLOYMENT_MARKER,
   309|      timestamp: nowIso(),
   310|    };
   311|    return ownerOnlyJson(failure, 400);
   312|  }
   313|
   314|  const allowlist = getIVXOwnerEmailAllowlist();
   315|  if (!allowlist.includes(email)) {
   316|    const failure: OwnerSessionFailure = {
   317|      success: false,
   318|      message: 'This email is not on the owner allowlist. Owner login is restricted to the configured owner.',
   319|      rootCause: 'email_not_allowlisted',
   320|      deploymentMarker: DEPLOYMENT_MARKER,
   321|      timestamp: nowIso(),
   322|    };
   323|    return ownerOnlyJson(failure, 403);
   324|  }
   325|
   326|  const supabaseUrl = resolveSupabaseUrl();
   327|  if (!supabaseUrl) {
   328|    const failure: OwnerSessionFailure = {
   329|      success: false,
   330|      message: 'Supabase URL is not configured on the backend.',
   331|      rootCause: 'supabase_url_not_configured',
   332|      deploymentMarker: DEPLOYMENT_MARKER,
   333|      timestamp: nowIso(),
   334|    };
   335|    return ownerOnlyJson(failure, 500);
