   338|  let adminClient: SupabaseClient;
   339|  try {
   340|    adminClient = createAdminClient();
   341|  } catch (error) {
   342|    const failure: OwnerSessionFailure = {
   343|      success: false,
   344|      message: error instanceof Error ? error.message : 'Failed to initialize Supabase admin client.',
   345|      rootCause: 'admin_client_init_failed',
   346|      deploymentMarker: DEPLOYMENT_MARKER,
   347|      timestamp: nowIso(),
   348|    };
   349|    return ownerOnlyJson(failure, 500);
   350|  }
   351|
   352|  // PRIMARY PATH — generateLink both resolves/creates the user AND returns
   353|  // the magic-link token in a SINGLE Supabase admin call. This replaces the
   354|  // prior 3-call sequence (listUsers → createUser → updateUserById) that
   355|  // consistently timed out on Render free tier.
