cd /home/user/rork-app

# Check soak test status while tests run
SOAK_PID=$(cat /tmp/ivx-soak-pid.txt 2>/dev/null)
if [ -n "$SOAK_PID" ] && kill -0 $SOAK_PID 2>/dev/null; then
  echo "Soak monitor running (PID $SOAK_PID)"
  cat /tmp/ivx-soak-results.json 2>/dev/null | bun -e '
    try {
      const d = JSON.parse(require("fs").readFileSync("/dev/stdin","utf8"));
      const elapsed = ((d.lastUpdate || Date.now()) - d.startTime) / 60000;
      console.log(`Elapsed: ${elapsed.toFixed(1)} min / 120 min`);
      console.log(`Requests: ${d.totalRequests}, Pass: ${d.passCount}, Fail: ${d.failCount}`);
      console.log(`502s: ${d.coldStart502s ?? 0}, Timeouts: ${d.timeouts ?? 0}, Restarts: ${d.restarts ?? 0}`);
      console.log(`SHA mismatches: ${d.shaMismatches ?? 0}, DB failures: ${d.dbFailures ?? 0}`);
      console.log(`P50: ${d.p50LatencyMs}ms, P95: ${d.p95LatencyMs}ms, Max: ${d.maxLatencyMs}ms`);
    } catch(e) { console.log("No results yet"); }
  '
else
  echo "Soak monitor NOT running — restarting..."
  nohup bun /tmp/ivx-soak-monitor-v2.ts > /tmp/ivx-soak-stdout.txt 2>&1 &
  echo $! > /tmp/ivx-soak-pid.txt
  echo "Restarted with PID $(cat /tmp/ivx-soak-pid.txt)"
fi

